import java.io.BufferedReader
import java.io.InputStreamReader

fun power(aValue: Long, bValue: Long): Long {
    var a = aValue
    var b = bValue
    var ans = 1L

    if (b == 0L) return 1L

    while (b > 0L) {
        if (b % 2L != 0L) {
            ans *= a
        }
        a *= a
        b /= 2L
    }
    return ans
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    var n = reader.readLine().trim().toLong()
    var i = 0L
    var index = 0L

    while (n > 0L) {
        val rem = n % 10L
        index += if (rem == 4L) {
            power(2L, i)
        } else {
            power(2L, i + 1L)
        }
        n /= 10L
        i++
    }

    println(index)
}

